const { TestEnvironment } = require('jest-environment-node')
const fs = require('node:fs')
const path = require('node:path')

// One JSON line per `test_done` and `test_retry`, to `<test file>.events.jsonl`: the test's name and
// its `errors` and `retryReasons` as the handler sees them. An entry circus keeps as it was pushed is
// `[error, asyncError]` (`tuple`); one jest-circus's `formatNodeAssertErrors` replaced at `test_done`
// is an object of its own (`keys`). Messages lose their colours and their stack frames.
const ANSI = /\u001b\[[0-9;]*m/g
const text = (value) =>
  String(value)
    .replace(ANSI, '')
    .split('\n')
    .filter((line) => !/^\s+at /.test(line))
    .join('\n')
const errorShape = (error) =>
  error !== null && typeof error === 'object' ? { message: text(error.message) } : { value: typeof error }
const entryShape = (entry) =>
  Array.isArray(entry)
    ? { tuple: entry.map(errorShape) }
    : entry !== null && typeof entry === 'object'
      ? { keys: Object.keys(entry).sort(), message: text(entry.message) }
      : { value: typeof entry }

class RecordingEnvironment extends TestEnvironment {
  constructor(config, context) {
    super(config, context)
    this.eventsFile = path.join(
      config.projectConfig.rootDir,
      `${path.basename(context.testPath).replace(/\.test\.ts$/, '')}.events.jsonl`,
    )
  }

  handleTestEvent(event) {
    if (event.name !== 'test_done' && event.name !== 'test_retry') return
    const { test } = event
    const line = {
      name: event.name,
      test: test.name,
      errors: test.errors.map(entryShape),
      retryReasons: test.retryReasons.map(entryShape),
    }
    fs.appendFileSync(this.eventsFile, JSON.stringify(line) + '\n')
  }
}

module.exports = RecordingEnvironment
